#!/usr/bin/env python3
"""Emit docker-compose.scale.yml for N crawler instances.

Generated rather than hand-written because the blocks are identical except for an index, and the
one thing that must never drift between them — CRAWLER_DATA_DIR — is exactly the thing a
copy-paste gets wrong. Two instances sharing a data directory share a frontier, an issue log and a
spend counter, and none of that fails loudly.

    python scripts/gen_scale_compose.py 7 > docker-compose.scale.yml

N is a DELIBERATE, RARE change. Growing is free: `domain_shards` assigns each domain once and never
moves it, so existing sites stay on their instance and only new ones reach the new containers.
SHRINKING strands frontiers — the orchestrator's shard.stranded() names which domains before you
do it.

    python scripts/gen_scale_compose.py --check 7 docker-compose.scale.yml   # CI: is it current?
"""
from __future__ import annotations

import sys

HEADER = '''# GENERATED by scripts/gen_scale_compose.py — do not edit by hand.
#   python scripts/gen_scale_compose.py {n} > docker-compose.scale.yml
#
# {n} crawler instances, ONE ENGINE PROCESS each — never CRAWLER_WORKERS>1.
#
# WHY PROCESSES, NOT WORKERS
# A page costs ~0.40 CPU-core-seconds and 97% of that is Python, so one CPython process tops out
# around 1.5-3 cores no matter how many tabs it owns. More throughput means more processes. The
# engine HAS a multiprocess mode and it must stay at 1: its children share no memory with the API
# parent, so the dashboard reads zero for the whole crawl, a child booting after STOP deletes the
# shared stop file and its siblings carry on, the paid-proxy spend cap is defeated, and resume
# breaks outright (measured: /v1/resumable returned []). All of that is parent/child divergence
# INSIDE one container. A container running exactly one engine has none of it.
#
# MEASURED, two instances on this box: 9.26 pages/s combined vs 3.90 for one — 2.37x, so the
# per-process ceiling is real and splitting it works.
#
# WHAT MAKES AN INSTANCE INDEPENDENT
# CRAWLER_DATA_DIR, and only that. It carries crawl_history.sqlite (the durable frontier and the
# dedup memory), issues.jsonl, site_auth.json and paid_proxy_usage.json. Instances share the
# `crawlerdata` VOLUME and differ by subdirectory, so there is still one thing to back up.
#
# instance 0 is the existing `crawler-api` on the bare /app/data — it already holds the corpus's
# frontier and history, and moving it would strand a live resume point.
#
#   docker compose -f docker-compose.yml -f docker-compose.datacentre.yml \\
#                  -f docker-compose.scale.yml up -d

x-crawler-instance: &crawler-instance
  extends:
    file: docker-compose.yml
    service: crawler-api
  # SHARE instance 0's image; do not build {n} of them.
  #
  # `extends` copies `build:`, so every sibling built its OWN image from the same Dockerfile — {n}
  # separate builds, {n} image IDs, and nothing keeping them in step. That is not a tidiness point:
  # after a code change, `docker compose build crawler-api` rebuilt exactly one of them, so the
  # fleet silently ran a MIX of old and new code. Measured — a new per-site filter worked on
  # instance 0 and was ignored by the other eleven, and the only symptom was a filter that
  # "didn't work".
  #
  # Resetting build and naming the image means there is one artefact: build crawler-api, recreate
  # the fleet, everyone runs the same bytes.
  build: !reset null
  image: mallory-crawler-crawler-api:latest
  restart: unless-stopped
  # `extends` copies depends_on, and the base crawler-api waits on minio-init — which the datacentre
  # overlay parks behind the `bundled` profile because the corpus lives in the mallory-data stack.
  # The overlay resets that for `crawler-api` BY NAME, so every sibling has to reset it too or the
  # whole project fails to load with "depends on undefined service".
  depends_on: !reset []
  # cpu_shares (relative weight), NOT cpus (hard CFS quota). Under a quota the scheduler throttles
  # the container, latency inflates, the 240s per-item watchdog fires, and _note_weak_host demotes
  # the host to concurrency 1 — so a CPU cap makes throughput collapse BELOW baseline instead of
  # levelling off. A weight just loses ties.
  #
  # CPUSET pins the whole fleet inside the crawler group's 20 cores (0-19). The box is divided
  # crawler 0-19 / L2 20-29 / SFL 30-34 / shared+OS 35-39. A cpuset is hard separation without the
  # quota throttling above: full speed inside the set, no access outside it.
  #
  # 30g is the crawler group's 400 GiB budget divided across the fleet + camofox + ingest +
  # orchestrator, and it is only safe because _cgroup_ram_percent lets the engine's RAM brake see
  # its own cgroup — it used to read the HOST's /proc/meminfo, so it never fired at ANY cap and a
  # 20g limit nearly OOM-killed three instances. Raised 28g -> 30g by trimming camofox
  # (32->16) and ingest (24->16), which were sized far above their measured use while a
  # real instance sat at 27.9 of 28 GiB.
  cpu_shares: 1024
  cpuset: "0-19"
  mem_limit: 30g
  # `default` must be listed explicitly: naming any network replaces the implicit one, and without
  # it an instance loses its own stack-mates (ingest, camofox).
  networks: [default, mallory-data]
  # No published port. Only the orchestrator talks to these and it is on the same network; a
  # published port per instance is {n} more things bound on the host for no reader.
  ports: !reset []
  expose: ["8099"]

services:

  # The orchestrator is the only thing that talks to the fleet, and CRAWLER_API_POOL is how it
  # learns the fleet exists. ORDER IS DATA, not presentation: the index into this list is the
  # instance number recorded in `domain_shards`, so reordering it routes sites to a container that
  # does not hold their frontier. APPEND ONLY.
  orchestrator:
    environment:
      CRAWLER_API_POOL: "{pool}"
'''

BLOCK = '''
  crawler-api-{i}:
    <<: *crawler-instance
    environment:
      CRAWLER_DATA_DIR: /app/data/i{i}
      # Paid egress has ONE owner (instance 0). The usage counter is a read-modify-write full
      # overwrite, so N writers do not merge their counts, they lose them — both read N, both write
      # N+1, and the daily cap is silently exceeded.
      BRIGHTDATA_ENABLED: "0"
      # C3 IS SHARED, NOT OWNED. It used to be "0" here so instance 0 owned the whole tier — but
      # instance 0 asks for CRAWLER_C3_WORKERS=12 against a CamoFox sized MAX_SESSIONS=12, so ONE
      # instance saturated the entire service with zero headroom, and the other {n}-1 could not
      # escalate to stealth rendering at all. A site that needs C3 on any other instance simply
      # failed. (CamoFox then wedged for 41 hours — browser alive at 147% CPU, every tab-create
      # timing out — which one client holding every session makes far likelier.)
      #
      # A SMALL SHARE EACH is the fix: {n} x 2 = 24 concurrent against MAX_SESSIONS=28, so every
      # instance can reach C3 and none can starve the rest. Raise this ONLY together with the
      # camofox service's MAX_SESSIONS/MAX_TABS_GLOBAL — the cap is global and silently queues.
      CRAWLER_C3_WORKERS: "2"
      # HOW MANY CamoFox userIds this instance rotates through. Must be set, and must match
      # C3_WORKERS: the default is 4, and camofox_client now derives its userId prefix from the
      # container hostname, so 4 x {n} instances = 48 DISTINCT sessions against MAX_SESSIONS=28 —
      # the service would evict and re-create contexts continuously. Before the prefix was made
      # per-instance every container asked for the same "crawler-0..3", which capped the whole
      # FLEET at 4 shared browser contexts (measured: activeSessions 4, 133 tab-create timeouts in
      # 10 minutes) — the opposite failure, from the same knob.
      #
      # 2 per instance x {n} = 24 <= 28, with each instance's 2 C3 workers owning one userId each.
      # More userIds than C3 workers buys nothing: a worker can only drive one tab at a time.
      CRAWLER_CAMOFOX_POOL: "2"
      # Sized for this instance's share of the catalogue, not the whole of it.
      # 4 -> 2 with the fleet pinned to 20 cores (was 40, uncapped). {n} instances x 4 was 48
      # simultaneous Chromium launches on 20 cores: load hit 137, BrowserType.launch blew its
      # 180s timeout on EVERY instance, and the fleet stored ZERO pages while looking busy.
      # Launch is the spike, not steady state — and at ~1.2 cores per concurrent render, 20 cores
      # admits ~16 renders fleet-wide anyway, so 24 browsers is still headroom over the ceiling.
      # Raise this only if the crawler's cpuset grows; see docker-compose.datacentre.yml.
      CRAWLER_BROWSERS: "2"
      CRAWLER_TABS_PER_BROWSER: "8"
'''


def render(n: int) -> str:
    if n < 2:
        raise SystemExit("N must be >= 2 — instance 0 is the existing crawler-api service")
    pool = ",".join(["http://crawler-api:8099"]
                    + [f"http://crawler-api-{i}:8099" for i in range(2, n + 1)])
    return HEADER.format(n=n, pool=pool) + "".join(BLOCK.format(i=i, n=n) for i in range(2, n + 1))


def main(argv: list[str]) -> int:
    # Windows redirects stdout in the console codepage, which turns every em-dash in the comments
    # into a mojibake byte and then makes --check fail to even read the file back. The generated
    # YAML is UTF-8 regardless of who runs the generator.
    try:
        sys.stdout.reconfigure(encoding="utf-8", newline="\n")
    except (AttributeError, ValueError):
        pass
    if len(argv) >= 3 and argv[0] == "--check":
        want = render(int(argv[1]))
        have = open(argv[2], encoding="utf-8").read()
        if want.strip() != have.strip():
            print(f"{argv[2]} is stale — regenerate with: "
                  f"python scripts/gen_scale_compose.py {argv[1]} > {argv[2]}", file=sys.stderr)
            return 1
        print(f"{argv[2]} is current for N={argv[1]}")
        return 0
    if not argv:
        raise SystemExit(__doc__)
    sys.stdout.write(render(int(argv[0])))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
